// Normalizar y validar TaskPayload<RiskAnalyzerInput>
const input = $input.first().json;

if (!input.taskId || !input.inputData || !input.inputData.clausesToEvaluate) {
  throw new Error('Payload inválido: taskId y inputData.clausesToEvaluate son requeridos.');
}

return [{
  json: {
    taskId: input.taskId,
    auditId: input.auditId,
    governingJurisdiction: input.inputData.governingJurisdiction || 'Delaware, USA / Global Standard',
    clausesToEvaluate: JSON.stringify(input.inputData.clausesToEvaluate, null, 2),
    partyAudited: input.inputData.partyAudited || 'CLIENT'
  }
}];

const rawOutput = $input.first().json.output || $input.first().json;

return [{
  json: {
    outputData: rawOutput,
    executedAt: new Date().toISOString()
  }
}];
